CREATE OR REPLACE FUNCTION public.catat_setoran(p_pengelola_id bigint, p_nasabah_id bigint, p_tanggal date, p_kunci uuid, p_item jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_id bigint;
    v_jumlah integer;
BEGIN
    IF p_tanggal IS NULL OR p_tanggal > (now() AT TIME ZONE 'Asia/Jakarta')::date THEN
        RAISE EXCEPTION 'Tanggal setoran harus diisi dan tidak boleh di masa depan.';
    END IF;
    IF jsonb_typeof(p_item) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'Rincian harus berupa daftar hasil penimbangan.';
    END IF;
    IF jsonb_array_length(p_item) = 0 THEN
        RAISE EXCEPTION 'Setoran memerlukan sedikitnya satu jenis sampah.';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_to_recordset(p_item) AS i(jenis_sampah_id integer, berat_kg numeric)
        WHERE i.jenis_sampah_id IS NULL OR i.berat_kg IS NULL
            OR NOT (i.berat_kg > 0 AND i.berat_kg < 1000000000)
            OR i.berat_kg <> round(i.berat_kg, 3)
    ) THEN
        RAISE EXCEPTION 'Periksa jenis sampah dan berat positif (maksimal tiga desimal).';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM akun WHERE id = p_pengelola_id AND peran = 'pengelola' AND aktif)
       OR NOT EXISTS (SELECT 1 FROM akun WHERE id = p_nasabah_id AND peran = 'nasabah' AND aktif) THEN
        RAISE EXCEPTION 'Pilih akun pengelola dan nasabah yang aktif.';
    END IF;

    INSERT INTO setoran (nasabah_id, pengelola_id, tanggal_setoran, kunci_permintaan)
    VALUES (p_nasabah_id, p_pengelola_id, p_tanggal, p_kunci)
    RETURNING id INTO v_id;

    INSERT INTO detail_setoran (setoran_id, jenis_sampah_id, berat_kg, harga_per_kg)
    SELECT v_id, i.jenis_sampah_id, i.berat_kg, h.harga_per_kg
    FROM jsonb_to_recordset(p_item) AS i(jenis_sampah_id integer, berat_kg numeric)
    JOIN LATERAL (
        SELECT harga_per_kg FROM harga_sampah
        WHERE jenis_sampah_id = i.jenis_sampah_id AND berlaku_mulai <= p_tanggal
        ORDER BY berlaku_mulai DESC LIMIT 1
    ) AS h ON true;

    GET DIAGNOSTICS v_jumlah = ROW_COUNT;
    IF v_jumlah <> jsonb_array_length(p_item) THEN
        RAISE EXCEPTION 'Jenis sampah atau tarif per kg belum tersedia pada tanggal setoran.';
    END IF;
    RETURN v_id;
END;
$function$
